# owner: platform
"""Plain text absence notices for parents."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


def _check_marks(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} given for"
                f" student {student.student_id}"
            )


def _render(student: Student, days: List[date]) -> str:
    dates = ", ".join(item.isoformat() for item in days)
    return (
        f"Notice: {student.first_name} {student.last_name}"
        f" missed {len(days)} day(s): {dates}."
    )


def build_notice(
    student: Student, marks: List[Mark]
) -> str:
    _check_marks(student, marks)
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return _render(student, days)
